import pytest
from mcp_types import CallToolRequestParams
from opentelemetry.trace import SpanKind, StatusCode
from mcp.server._otel import OpenTelemetryMiddleware
from mcp.server.context import CallNext
from mcp.server.lowlevel.server import Server
from .conftest import SpanCapture
from .test_runner import Ctx, SrvT, connected_runner

@pytest.fixture
def server() -> SrvT:
    async def list_tools(ctx: Ctx, params):
        return []  # placeholder
    return Server(name="test-server", version="0.0.1", on_list_tools=list_tools)

async def _ok_tool(ctx: Ctx, params: CallToolRequestParams) -> dict:
    return {"content": [], "isError": False}

@pytest.mark.anyio
async def test_tool_call_records_arguments_attribute(server: SrvT, spans: SpanCapture):
    server.add_request_handler("tools/call", CallToolRequestParams, _ok_tool)
    async with connected_runner(server) as (client, _):
        spans.clear()
        await client.send_raw_request("tools/call", {"name": "mytool", "arguments": {"a": 1, "b": "x"}})
    [span] = [s for s in spans.finished() if s.kind == SpanKind.SERVER]
    assert span.attributes is not None
    # The arguments dict should be stringified in the attribute.
    assert span.attributes["mcp.tool.arguments"] == "{'a': 1, 'b': 'x'}"
    assert span.status.status_code == StatusCode.UNSET"
}
